#![allow(unused_imports)]
use verus::prelude::*;
use std::io::{self, Read};

//----------------------------------------------------------------
// Spec functions: count the number of adjacent ("S","F")
// or ("F","S") pairs in a Verus sequence.
//----------------------------------------------------------------

#[verifier::spec]
#[verifier::decreases(s.len())]
fn sf_count(s: Seq<char>) -> nat {
    if s.len() < 2 {
        0
    } else {
        let head = s.index(0);
        let next = s.index(1);
        (if head == 'S' && next == 'F' { 1 } else { 0 })
          + sf_count(s.slice(1, s.len()))
    }
}

#[verifier::spec]
#[verifier::decreases(s.len())]
fn fs_count(s: Seq<char>) -> nat {
    if s.len() < 2 {
        0
    } else {
        let head = s.index(0);
        let next = s.index(1);
        (if head == 'F' && next == 'S' { 1 } else { 0 })
          + fs_count(s.slice(1, s.len()))
    }
}

//----------------------------------------------------------------
// The main solver, with pre‐ and post‐conditions.
//----------------------------------------------------------------

#[requires(s.len() == n)]
// we always return either length‐3 ("YES") or length‐2 ("NO")
#[ensures(
    result.len() == 
       if sf_count(s@) > fs_count(s@) { 3 } else { 2 }
)]
// exactly "YES" iff #SF > #FS
#[ensures(
    (sf_count(s@) > fs_count(s@)) <==> result == vec!['Y','E','S']
)]
fn solve(n: usize, s: Vec<char>) -> Vec<char> {
    let (mut count_sf, mut count_fs) = (0, 0);
    for i in 1..n {
        match (s[i - 1], s[i]) {
            ('S', 'F') => count_sf += 1,
            ('F', 'S') => count_fs += 1,
            _ => {}
        }
    }
    if count_sf > count_fs {
        vec!['Y', 'E', 'S']
    } else {
        vec!['N', 'O']
    }
}

fn main() {
    // Read the entire stdin into a string
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();

    // Tokenize on whitespace
    let mut it = input.split_whitespace();

    // Parse n
    let n: usize = it.next().unwrap().parse().unwrap();
    // Read the sequence of 'S' / 'F'
    let sequence: Vec<char> = it.next().unwrap().chars().collect();

    // Compute the answer
    let answer = solve(n, sequence);

    // Print as a contiguous string, e.g. "YES" or "NO"
    let output: String = answer.into_iter().collect();
    println!("{}", output);
}